static int calls = 0;

public static int bs(int[] a, int t, int lo, int hi) {
    calls++;
    if (lo > hi) {
        return -1;
    }
    int mid = (lo + hi) / 2;
    if (a[mid] == t) {
        return mid;
    }
    if (a[mid] < t) {
        return bs(a, t, mid + 1, hi);
    }
    return bs(a, t, lo, mid - 1);
}
```

