static int calls = 0;

public static int pow(int b, int e) {
    calls++;
    if (e == 0) {
        return 1;
    }
    if (e % 2 == 0) {
        int h = pow(b, e / 2);
        return h * h;
    }
    return b * pow(b, e - 1);
}
```

