public static void selSort(int[] a, int start) {
    if (start >= a.length - 1) {
        return;
    }
    int min = start;
    for (int i = start + 1; i < a.length; i++) {
        if (a[i] < a[min]) {
            min = i;
        }
    }
    int t = a[start];
    a[start] = a[min];
    a[min] = t;
    String s = "";
    for (int v : a) {
        s += v;
    }
    System.out.print(s + " ");
    selSort(a, start + 1);
}
```

